import { readFileSync } from 'node:fs'
import { DiscordAPIError } from 'discord.js'

// =============================================================================
//   Settings
// =============================================================================

/** Fill the process environment with fake settings based on .env.example, fast enough for tests; dotenv never overrides what is already set. `overrides` replaces any of them. */
export function useFakeSettings (overrides = {}) {
  const template = readFileSync(new URL('../.env.example', import.meta.url), 'utf8')
  for (const [, name, value] of template.matchAll(/^([A-Z][A-Z0-9_]*)=(.*)$/gm)) process.env[name] = value.trim()
  Object.assign(process.env, {
    BOT_TOKEN: 'fake', APPLICATION_ID: 'fake', REPLY_CATEGORY_IDS: 'cat1', STAFF_ROLE_IDS: '',
    SWAP_WATCH_INTERVAL_SECONDS: '1', JITTER_PERCENT: '0', MESON_RETRIES: '0', TICKET_RETRY_SECONDS: '1', TICKET_RETRY_MAX_SECONDS: '1',
  }, overrides)
  // The bot's own logging would only bury the test results.
  console.log = () => {}
  console.warn = () => {}
  console.error = () => {}
}

// =============================================================================
//   Fake Meson
// =============================================================================

/** Events of a swap still moving. */
export const MOVING = [{ name: 'BONDED', hash: '0xaa' }]

/** Events of a finished swap. */
export const DONE = [{ name: 'EXECUTED', hash: '0xaa' }, { name: 'RELEASED', hash: '0xbb' }]

/** A swap ID made from one repeated character. */
export const swapId = (c) => '0x' + String(c).repeat(64)

/** An encoded swap from BNB token 34 (or `outChain`) to Solana token 2, with a deadline an hour away. */
export function encodedSwap ({ outChain = '02ca', outToken = '22' } = {}) {
  const deadline = Math.floor(Date.now() / 1000) + 3600
  return `0x01${(5000000).toString(16).padStart(10, '0')}${'00'.repeat(10)}${'00'.repeat(5)}${deadline.toString(16).padStart(10, '0')}${outChain}${outToken}01f502`
}

/** One raw swap record, as Meson's API sends it. */
export const swapRecord = (id, events, encoded = encodedSwap()) => ({ _id: id, encoded, events, srFee: 0, lpFee: 0, fromTo: ['a', 'b'], created: new Date().toISOString() })

/** A JSON response. */
export const json = (body, status = 200) => new Response(JSON.stringify(body), { status })

/**
 * Replace fetch with a fake Meson.
 * @param {object} world
 * @param {Record<string, object[]>} [world.events] each swap's current events, by swap ID
 * @param {Record<string, object>} [world.search] what the search answers, by query (default: not found)
 * @param {string[]} [world.bad] swap IDs whose record is malformed
 * @returns {{requests: number}} a live count of swap requests
 */
export function stubMeson ({ events = {}, search = {}, bad = [] } = {}) {
  const count = { requests: 0 }
  globalThis.fetch = async (url) => {
    const u = String(url)
    if (u.includes('rpcs.meson.fi')) return json({ data: {} })
    const q = u.match(/\/search\?q=(.+)$/)
    if (q) return search[decodeURIComponent(q[1])] ? json({ result: search[decodeURIComponent(q[1])] }) : json({ error: { message: 'Swap not found' } }, 404)
    if (u.includes('/address/')) return json({ result: { list: [] } })
    count.requests++
    const ids = u.match(/\/api\/v1\/swap\/(.+)$/)[1].split(/,|%2C/)
    const records = ids.map((id) => swapRecord(id, events[id] ?? MOVING, bad.includes(id) ? 'garbage' : undefined))
    return json({ result: ids.length > 1 ? records : records[0] })
  }
  return count
}

