//   Fake Discord
// =============================================================================

/** Wait this many milliseconds. */
export const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

/** A fake server with one ticket channel. `posted` collects everything the bot sends; `message` builds a message in the channel. */
export function makeWorld (channelId) {
  const me = { id: 'BOT' }
  const client = { user: me, channels: { cache: new Map() }, guilds: { cache: new Map() } }
  const posted = []
  let next = 1000
  const message = (id, author, fields = {}, hooks = {}) => {
    const m = {
      id: String(id), author, client, channel, channelId: channel.id, createdTimestamp: Date.now(), member: null, content: '', embeds: [], reference: null, ...fields,
      reply: async (payload) => {
        const failure = hooks.failReply?.()
        if (failure) throw failure
        posted.push(payload)
        const reply = message(++next, me, { ...payload, reference: { messageId: m.id } })
        channel.history.push(reply) // as on Discord, what the bot posts becomes part of the channel's history
        return reply
      },
      edit: async (payload) => { Object.assign(m, payload); m.edits = (m.edits ?? 0) + 1; return m },
      delete: async () => { m.deleted = true },
    }
    return m
  }
  const channel = {
    id: channelId, name: channelId, client, parentId: 'cat1', history: [],
    isThread: () => false, isTextBased: () => true, isVoiceBased: () => false,
    permissionsFor: () => ({ has: () => true }),
    send: async (payload) => { posted.push(payload); const sent = message(++next, me, payload); channel.history.push(sent); return sent },
    messages: { fetch: async () => { const page = new Map(channel.history.map((m) => [m.id, m])); page.last = () => channel.history[0]; return page } },
  }
  const guild = { members: { me: { id: 'BOT' }, fetch: async () => {} }, channels: { cache: new Map([[channel.id, channel]]), fetchActiveThreads: async () => ({ threads: new Map() }) } }
  channel.guild = guild
  client.channels.cache.set(channel.id, channel)
  client.guilds.cache.set('guild', guild)
  return { me, client, channel, posted, message, user: { id: 'USER', bot: false } }
}

/** A Discord refusal (Missing Permissions). */
export const refusal = () => Object.assign(Object.create(DiscordAPIError.prototype), { status: 403, code: 50013, message: 'Missing Permissions' })

/** The plain-text messages among what the bot posted. */
export const texts = (posted) => posted.map((p) => p.content ?? '')
